import assert from 'node:assert';
import test from 'node:test';
import { createState, frame, WIDTH, HEIGHT, BRICK_TOP, BRICK_H, BRICK_W } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {}
};

test('D1: Ball should bounce off brick (not just pass through)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball so it's about to hit the brick from above
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 8;
  state.ball.vx = 0;
  state.ball.vy = 100; // Moving down

  // We need to simulate the movement and then the frame
  // Since step() doesn't handle bricks, and frame() does collision detection
  // We simulate one step and one frame
  state.ball.y += state.ball.vy * 0.01; // Move slightly into the brick

  const oldVy = state.ball.vy;
  frame(mockCtx, state);

  assert.notStrictEqual(state.ball.vy, oldVy, 'Ball velocity should have changed after brick collision');
});

test('D3: Ball should not stick to brick (position resolution)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y + 2; // Deep inside the brick
  state.ball.vy = 100;

  frame(mockCtx, state);

  // After collision, the ball should be pushed out of the brick
  // If it's still colliding, it's "sticky"
  const isColliding = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h
  );
  assert.strictEqual(isColliding, false, 'Ball should be pushed out of the brick after collision');
});

test('D4: Ball should not suffer from double inversion at seams', () => {
  const state = createState(1);
  // Use two adjacent bricks
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];

  state.ball.x = brick1.x + brick1.w; // Exactly on the seam
  state.ball.y = brick1.y + BRICK_H / 2;
  state.ball.vx = 100; // Moving right
  state.ball.vy = 0;

  // Force both bricks to be alive
  brick1.alive = true;
  brick2.alive = true;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx < 0, true, 'Ball should have bounced back from the seam');
});

test('D5: Ball should bounce off corners (both axes)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball to hit the top-left corner
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y - 2;
  state.ball.vx = 100;
  state.ball.vy = 100;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx < 0, true, 'vx should be inverted');
  assert.strictEqual(state.ball.vy < 0, true, 'vy should be inverted');
});

test('D2: Ball should not tunnel through bricks at high speed', () => {
  const state = createState(10); // Level 10 = high speed
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; // Very fast

  // Simulate one large step that would skip the brick
  const dt = 0.05;
  state.ball.y += state.ball.vy * dt; // y = brick.y - 10 + 50 = brick.y + 40

  // Now y is 40, brick.y is 0, brick.h is 20. 
  // Ball.y - ball.r = 40 - 7 = 33.
  // Since 33 > 20, the ball is already below the brick.
  // Discrete collision detection will fail.

  frame(mockCtx, state);

  // This is a "conceptual" test. Today it will definitely fail because 
  // frame() only checks current position.
  // The expected behavior is that it should have bounced.
  assert.strictEqual(state.ball.vy < 0, true, 'Ball should have bounced even if it tunneled');
});

# Symptôme : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond
- **Famille** : résolution de base
- **Symptôme joueur** : la balle traverse la brique sans changer de direction.
- **Cause** : `game/neon.js:186` — la collision est détectée et la brique est détruite, mais aucune modification de `ball.vx` ou `ball.vy` n'est effectuée.
- **Invariant violé** : toute collision avec un obstacle doit entraîner une réflexion du vecteur vitesse.
- **Déclencheur** : n'importe quelle collision avec une brique.
- **Attendu** : `ball.vx` ou `ball.vy` doit être inversé selon la face touchée.
- **Référence** : [Standard AABB Response] — Inversion de la composante de vitesse perpendiculaire à la face de collision.
- **Cas test** :
  ```js
  test('D1: Ball should bounce off brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - 8;
    state.ball.vy = 100;
    frame(mockCtx, state);
    assert.notStrictEqual(state.ball.vy, 100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball velocity should have changed after brick collision`
- **Discrimine** : refuse une implémentation qui se contente de détruire la brique sans rebond.
- **Vert quand** : la vitesse de la balle est modifiée après collision.
- **Révélé par** : -

## D3 — Collant (Stickiness)
- **Famille** : Collant
- **Symptôme joueur** : la balle semble "vibrer" ou rester coincée dans la brique.
- **Cause** : `game/neon.js:186` — inversion de la vitesse sans repositionnement de la balle hors de l'AABB.
- **Invariant violé** : après résolution, la balle doit être hors du rectangle.
- **Déclencheur** : collision profonde où `ball.y + ball.r` pénètre significativement dans la brique.
- **Attendu** : la position de la balle est ajustée pour être tangente à la face de la brique.
- **Référence** : [AABB Collision Resolution] — Repositionner l'objet sur le bord de l'obstacle pour éviter les collisions multiples.
- **Cas test** :
  ```js
  test('D3: Ball should not stick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.y = brick.y + 2; 
    frame(mockCtx, state);
    assert.strictEqual(collides(state.ball, brick), false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be pushed out of the brick after collision`
- **Discrimine** : refuse une correction naïve qui inverse `vy` mais laisse la balle à l'intérieur de la brique.
- **Vert quand** : `collides(ball, brick)` est faux après le rebond.
- **Révélé par** : D1

## D4 — Double inversion (Seams)
- **Famille** : Double inversion
- **Symptôme joueur** : la balle traverse une rangée de briques en ignorant les jointures.
- **Cause** : boucle `for (const brick of state.bricks)` dans `frame()` qui traite chaque brique indépendamment.
- **Invariant violé** : un rebond par passe et par axe.
- **Déclencheur** : balle touchant exactement la couture entre deux briques.
- **Attendu** : un seul rebond est appliqué même si deux briques sont touchées.
- **Référence** : [Tile Seam Ghost Collision] — Résolution des collisions de grille en privilégiant l'axe de moindre pénétration ou en stoppant après le premier rebond valide.
- **Cas test** :
  ```js
  test('D4: Seam collision', () => {
    const state = createState(1);
    state.ball.x = state.bricks[0].x + state.bricks[0].w; 
    state.ball.vx = 100;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vx < 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced back from the seam`
- **Discrimine** : refuse une implémentation qui boucle sur toutes les briques et inverse la vitesse pour chacune d'elles.
- **Vert quand** : la vitesse est inversée une seule fois.
- **Révélé par** : D1

## D5 — Coins (Corners)
- **Famille** : Face vs coin
- **Symptôme joueur** : rebond imprévisible ou unidirectionnel sur les angles.
- **Cause** : `game/neon.js:186` — absence de logique de détection de coin.
- **Invariant violé** : sur un coin, les deux axes de vitesse doivent être inversés.
- **Déclencheur** : collision où la pénétration sur X et Y est similaire.
- **Attendu** : `vx = -vx` ET `vy = -vy`.
- **Référence** : [AABB Corner Resolution] — Inversion des deux axes si la collision se produit dans la zone d'angle.
- **Cas test** :
  ```js
  test('D5: Corner bounce', () => {
    const state = createState(1);
    state.ball.x = state.bricks[0].x - 2;
    state.ball.y = state.bricks[0].y - 2;
    state.ball.vx = 100;
    state.ball.vy = 100;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vx < 0 && state.ball.vy < 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: vx should be inverted`
- **Discrimine** : refuse une correction qui n'inverse qu'un seul axe.
- **Vert quand** : les deux composantes de vitesse sont inversées.
- **Révélé par** : D1

## D2 — Traversée (Tunneling)
- **Famille** : Traversée
- **Symptôme joueur** : la balle passe à travers la brique sans aucune réaction à haute vitesse.
- **Cause** : détection discrète dans `frame()` basée sur la position actuelle.
- **Invariant violé** : aucun obstacle franchi sans rebond, quel que soit le pas.
- **Déclencheur** : `ballSpeed(level) * dt > BRICK_H + 2 * BALL_R`.
- **Attendu** : détection du franchissement entre la position précédente et actuelle.
- **Référence** : [Swept AABB] — calcul du temps d'impact (t) entre deux positions.
- **Cas test** :
  ```js
  test('D2: Tunneling', () => {
    const state = createState(10);
    state.ball.y = state.bricks[0].y - 10; 
    state.ball.vy = 1000;
    state.ball.y += state.ball.vy * 0.05; 
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vy < 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced even if it tunneled`
- **Discrimine** : refuse la détection discrète simple.
- **Vert quand** : la balle rebondit même si elle a franchi la brique en un pas.
- **Révélé par** : -

